#include "elit21/config/Config.h"
#include <sqlite3.h>
#include <iostream>
int main(int argc,char**argv){if(argc<4){std::cerr<<"usage: product_mapping_editor <config> <aliexpress_product_id> <shopify_product_gid>\n";return 2;}auto c=elit21::Config::load(argv[1]);if(!c){std::cerr<<c.error()<<'\n';return 3;}sqlite3*db=nullptr;if(sqlite3_open(c.value().app.database.c_str(),&db)!=SQLITE_OK){std::cerr<<(db?sqlite3_errmsg(db):"open failed")<<'\n';if(db)sqlite3_close(db);return 4;}sqlite3_stmt*st=nullptr;const char*sql="UPDATE products SET shopify_product_id=?,updated_at=CURRENT_TIMESTAMP WHERE aliexpress_product_id=?";if(sqlite3_prepare_v2(db,sql,-1,&st,nullptr)!=SQLITE_OK){std::cerr<<sqlite3_errmsg(db)<<'\n';sqlite3_close(db);return 5;}sqlite3_bind_text(st,1,argv[3],-1,SQLITE_TRANSIENT);sqlite3_bind_text(st,2,argv[2],-1,SQLITE_TRANSIENT);const int rc=sqlite3_step(st);const int changed=sqlite3_changes(db);sqlite3_finalize(st);sqlite3_close(db);if(rc!=SQLITE_DONE){std::cerr<<"update failed\n";return 6;}std::cout<<"mapping updated rows="<<changed<<'\n';return changed>0?0:7;}
